protected final String getForRetrieveForEditDelete(final Class<?> pClass,
    final String pAction) {
    if (pClass == SubaccountLine.class || pClass == Account.class) {
      return PrcAccEntityWithSubaccRetrieve.class.getSimpleName();
    } else if (pClass == BankStatementLine.class
      && pAction.equals("entityEdit")) {
      return PrcBankStatementLineGfe.class.getSimpleName();
    } else if (pAction.equals("entityEdit") && (pClass == SalesInvoice.class
      || pClass == PurchaseInvoice.class)) {
      return PrcInvoiceGfe.class.getSimpleName();
    } else if (pAction.equals("entityEdit")
      && (pClass == SalesInvoiceServiceLine.class
        || pClass == PurchaseInvoiceServiceLine.class)) {
      return PrcInvoiceLnGfe.class.getSimpleName();
    } else if (pAction.equals("entityEdit")
      && pClass == PurchaseReturn.class) {
      return PrcPurchRetGfe.class.getSimpleName();
    } else if (pAction.equals("entityEdit")
      && pClass == SalesReturn.class) {
      return PrcSalesRetGfe.class.getSimpleName();
    } else if (pClass == PaymentFrom.class || pClass == PaymentTo.class
      || pClass == PrepaymentFrom.class || pClass == PrepaymentTo.class
        || pClass == AdditionCostLine.class) {
      return PrcAccEntityPbWithSubaccEditDelete.class.getSimpleName();
    } else if (pClass == AccountingEntries.class) {
      return PrcInpAccEntriesRetrieve.class.getSimpleName();
    } else if (IPersistableBase.class.isAssignableFrom(pClass)) {
      return PrcEntityPbEditDelete.class.getSimpleName();
    } else {
      if (this.hldAddEntitiesProcessorNames != null) {
        String name = this.hldAddEntitiesProcessorNames
          .getForRetrieveForEditDelete(pClass);
        if (name != null) {
          return name;
        }
      }
      return PrcEntityRetrieve.class.getSimpleName();
    }
  }

